        const cand = dp[i - d - 1][t - 1] + A[i - 1] * A[i - d - 1];
        if (cand > dp[i][t]) {
          dp[i][t] = cand;
          take[i][t] = true;
        }
      }
    }
  }
  const pairs = [];
  let i = n, t = k;
  while (t > 0 && i > 0) {
    if (take[i][t]) {
      pairs.push([i - d, i]); // 1-based indices of the pair
      i = i - d - 1;
      t--;
    } else {
      i--;
    }
  }
  pairs.reverse();
  return { value: dp[n][k], pairs };
}
